program2='''from collections import Counter

def _period(grid):
    scores = []
    for period in range(1, 11):
        matches = total = 0
        for r, row in enumerate(grid):
            if r < 3:
                continue
            buckets = [[] for _ in range(period)]
            for c in range(3, len(row)):
                if row[c] != 0:
                    buckets[c % period].append(row[c])
            matches += sum(max(Counter(bucket).values()) for bucket in buckets if bucket)
            total += sum(len(bucket) for bucket in buckets)
        scores.append((period, matches / total if total else 0.0))
    peak = max(score for _, score in scores)
    return min(period for period, score in scores if score >= peak - 0.01)

def transform(grid):
    out = [row[:] for row in grid]
    period = _period(grid)

    for r, row in enumerate(grid):
        width = len(row)
        if r < 3:
            for c in range(width):
                if row[c] == 0:
                    out[r][c] = 1 if r < 2 or c < 2 else 4
            continue

        buckets = [[] for _ in range(period)]
        for c in range(3, width):
            if row[c] != 0:
                buckets[c % period].append(row[c])
        modes = [Counter(bucket).most_common(1)[0][0] if bucket else None for bucket in buckets]
        known = [(c, row[c]) for c in range(3, width) if row[c] != 0]

        onset = None
        for start in range(3, width):
            first = [(c, value) for c, value in known if c >= start][:period]
            if len(first) == period and all(modes[c % period] == value for c, value in first):
                onset = start
                break

        for c in range(width):
            if row[c] != 0:
                if c >= 3 and onset is not None and c >= onset and modes[c % period] is not None:
                    out[r][c] = modes[c % period]
                continue
            if c < 3:
                out[r][c] = 1 if c < 2 else 4
            else:
                value = modes[c % period]
                if value is None:
                    nearest = min(known, key=lambda item: abs(item[0] - c))
                    value = nearest[1]
                out[r][c] = value
    return out
'''
